// Una hoja vacía puede producir un objeto vacío.
// Lo excluimos, pero conservamos los registros existentes.
const eventos = $input.all()
  .map(item => item.json)
  .filter(fila => Object.keys(fila).length > 0);

return [{
  json: {
    eventos,
  },
}];

const eventos = $('Agrupar eventos').first().json.eventos;

const inscripciones = $input.all()
  .map(item => item.json)
  .filter(fila => Object.keys(fila).length > 0);

const ahora = Date.now();
const confirmadasPorEvento = new Map();
const idsEventos = new Set();

function texto(valor) {
  return typeof valor === 'string' ? valor.trim() : '';
}

// Contamos únicamente las inscripciones que ocupan cupo.
for (const inscripcion of inscripciones) {
  if (!['CONFIRMADA', 'ASISTIO'].includes(inscripcion.estado)) {
    continue;
  }

  const eventoId = texto(inscripcion.evento_id);

  if (!eventoId || !inscripcion.inscripcion_id) {
    throw new Error('Existe una inscripción confirmada incompleta.');
  }

  confirmadasPorEvento.set(
    eventoId,
    (confirmadasPorEvento.get(eventoId) ?? 0) + 1
  );
}

const listado = [];

for (const evento of eventos) {
  // El catálogo público excluye borradores, cerrados y cancelados.
  if (evento.estado !== 'PUBLICADO') {
    continue;
  }

  const eventoId = texto(evento.evento_id);

  if (!eventoId || idsEventos.has(eventoId)) {
    throw new Error('Existe un evento publicado sin ID o con ID duplicado.');
  }

  idsEventos.add(eventoId);

  const fecha = texto(evento.fecha);
  const hora = texto(evento.hora);

  const fechaUTC = /^\d{4}-\d{2}-\d{2}$/.test(fecha)
    ? new Date(`${fecha}T00:00:00.000Z`)
    : new Date(NaN);

  const fechaValida =
    Number.isFinite(fechaUTC.getTime()) &&
    fechaUTC.toISOString().slice(0, 10) === fecha;

  const horaValida = /^([01]\d|2[0-3]):[0-5]\d$/.test(hora);

  if (!fechaValida || !horaValida) {
    throw new Error('Existe un evento publicado con fecha u hora inválida.');
  }

  // Fecha y hora de Colombia.
  const inicio = new Date(`${fecha}T${hora}:00-05:00`).getTime();

  if (inicio <= ahora) {
    continue;
  }

  const capacidad = Number(evento.capacidad);
  const confirmadas = confirmadasPorEvento.get(eventoId) ?? 0;

  if (!Number.isSafeInteger(capacidad) || capacidad <= 0) {
    throw new Error('Existe un evento publicado con capacidad inválida.');
  }

  if (confirmadas > capacidad) {
    throw new Error('Las inscripciones confirmadas exceden la capacidad.');
  }

  const disponibles = capacidad - confirmadas;

  // Seleccionamos explícitamente los campos públicos.
  // No enviamos filas internas ni datos personales de inscritos.
  listado.push({
    evento_id: eventoId,
    nombre: texto(evento.nombre),
    categoria: texto(evento.categoria),
    descripcion: texto(evento.descripcion),
    fecha,
    hora,
    zona_horaria: 'America/Bogota',
    lugar: texto(evento.lugar),
    capacidad,
    imagen_url: texto(evento.imagen_url),
    organizador: texto(evento.organizador),
    estado: 'PUBLICADO',
    inscripciones_confirmadas: confirmadas,
    cupos_disponibles: disponibles,
    disponibilidad: disponibles > 0 ? 'CON_CUPOS' : 'LISTA_ESPERA',
  });
}

// Primero aparecen los eventos más próximos.
// Los formatos AAAA-MM-DD y HH:mm permiten ordenar así.
listado.sort((a, b) =>
  `${a.fecha}T${a.hora}`.localeCompare(`${b.fecha}T${b.hora}`) ||
  a.evento_id.localeCompare(b.evento_id)
);

const consultaId = `CONS-${$execution.id}`;

return [{
  json: {
    respuesta: {
      ok: true,
      data: {
        eventos: listado,
      },
      meta: {
        total: listado.length,
        consulta_id: consultaId,
      },
    },
    consulta: {
      consulta_id: consultaId,
      fecha: new Date().toISOString(),
      tipo: 'LISTADO',
      evento_id: '',
      categoria: '',
      resultado_count: listado.length,
      visitor_id: `ANON-${$execution.id}`,
      status_http: 200,
    },
  },
}];

