const base = $input.first().json;
const query = $('Webhook - Catálogo público').first().json.query ?? {};

const errores = [];
const parametrosPermitidos = ['evento_id', 'categoria', 'visitor_id'];

const categoriasPermitidas = [
  'Networking tecnológico',
  'Networking emprendedor',
  'Networking profesional',
];

function tieneParametro(nombre) {
  return Object.prototype.hasOwnProperty.call(query, nombre);
}

// Solo aceptamos parámetros de texto individuales, no listas ni objetos.
function leerParametro(nombre, maximo) {
  if (!tieneParametro(nombre)) {
    return '';
  }

  const valor = query[nombre];

  if (
    typeof valor !== 'string' ||
    !valor.trim() ||
    valor.trim().length > maximo
  ) {
    errores.push(`El parámetro ${nombre} no tiene un formato válido.`);
    return '';
  }

  return valor.trim();
}

if (Object.keys(query).some(clave => !parametrosPermitidos.includes(clave))) {
  errores.push('La consulta contiene parámetros no admitidos.');
}

const eventoId = leerParametro('evento_id', 80);
const categoria = leerParametro('categoria', 80);
const visitante = leerParametro('visitor_id', 80);

const identificadorValido = /^[A-Za-z0-9_-]{1,80}$/;

if (eventoId && !identificadorValido.test(eventoId)) {
  errores.push('evento_id contiene caracteres no permitidos.');
}

if (categoria && !categoriasPermitidas.includes(categoria)) {
  errores.push('La categoría no es válida.');
}

if (visitante && !identificadorValido.test(visitante)) {
  errores.push('visitor_id contiene caracteres no permitidos.');
}

if (tieneParametro('evento_id') && tieneParametro('categoria')) {
  errores.push('Utiliza evento_id o categoria, pero no ambos a la vez.');
}

// Clasificamos la intención de la consulta para el registro.
const tipo = tieneParametro('evento_id')
  ? 'DETALLE'
  : tieneParametro('categoria')
    ? 'FILTRO'
    : 'LISTADO';

let eventos = base.respuesta.data.eventos;
let statusHttp = 200;
let error = null;

if (errores.length > 0) {
  eventos = [];
  statusHttp = 400;

  error = {
    codigo: 'CONSULTA_INVALIDA',
    mensaje: 'Revisa los parámetros de la consulta.',
    detalles: errores,
  };
} else if (eventoId) {
  eventos = eventos.filter(evento => evento.evento_id === eventoId);

  if (eventos.length === 0) {
    statusHttp = 404;
    error = {
      codigo: 'EVENTO_NO_ENCONTRADO',
      mensaje: 'No se encontró un evento público disponible con ese ID.',
    };
  }
} else if (categoria) {
  eventos = eventos.filter(evento => evento.categoria === categoria);
}

// Si no se proporciona un visitante válido, conservamos el ID anónimo.
// visitor_id sirve para trazabilidad, nunca para autenticar usuarios.
const visitorId = visitante && identificadorValido.test(visitante)
  ? visitante
  : base.consulta.visitor_id;

const respuesta = {
  ok: statusHttp === 200,
  data: statusHttp === 200 ? { eventos } : null,
  meta: {
    total: eventos.length,
    consulta_id: base.consulta.consulta_id,
    tipo,
  },
};

if (error) {
  respuesta.error = error;
}

return [{
  json: {
    respuesta,
    consulta: {
      ...base.consulta,
      tipo,
      evento_id: identificadorValido.test(eventoId) ? eventoId : '',
      categoria: categoriasPermitidas.includes(categoria) ? categoria : '',
      resultado_count: eventos.length,
      visitor_id: visitorId,
      status_http: statusHttp,
    },
  },
}];
